<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserAcceptedTermsOfUseUserAccessor
{
    private UserAcceptedTermsOfUseUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserAcceptedTermsOfUseUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserAcceptedTermsOfUseUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserAcceptedTermsOfUseUserVO::from($user);
        return $copy;
    }
}
